    if (!file3) throw new CoreError("no_settings", "This folder has no settings.json to update.");
    const settings = JSON.parse(file3.text);
    settings.recorders = { ...settings.recorders ?? {}, [call.meta.recorder]: { ...settings.recorders?.[call.meta.recorder] ?? {}, speaker_self: input3.speaker } };
